import os, io
input = io.BytesIO(os.read(0, os.fstat(0).st_size)).readline
MOD1 = 100000007
MOD2 = 100000007
evenStrDict = {}
oddStrDict = {}
cnt = 0
N = int(input())
for _ in range(N):
	p = input()
	countList = [0] * 26
	for elem in p:
		if elem < 97:
			break
		countList[elem - 97] += 1
	hash1 = 0
	hash2 = 0
	for i in range(26):
		if countList[i] % 2 != 0:
			hash1 += 1 << i
			hash1 %= MOD1
			hash2 += 1 << i
			hash2 %= MOD2
	if len(p) % 2 != 0:
		curKey = (hash1, hash2)
		if curKey in oddStrDict:
			cnt += oddStrDict[curKey]
			oddStrDict[curKey] += 1
		else:
			oddStrDict[curKey] = 1
		for i in range(26):
			newHash1 = hash1
			newHash2 = hash2
			if countList[i] % 2 != 0:
				newHash1 -= 1 << i
				newHash1 %= MOD1
				newHash2 -= 1 << i
				newHash2 %= MOD2
			else:
				newHash1 += 1 << i
				newHash1 %= MOD1
				newHash2 += 1 << i
				newHash2 %= MOD2
			newKey = (newHash1, newHash2)
			if newKey in evenStrDict:
				cnt += evenStrDict[newKey]
	else:
		curKey = (hash1, hash2)
		if curKey in evenStrDict:
			cnt += evenStrDict[curKey]
			evenStrDict[curKey] += 1
		else:
			evenStrDict[curKey] = 1
		for i in range(26):
			newHash1 = hash1
			newHash2 = hash2
			if countList[i] % 2 != 0:
				newHash1 -= 1 << i
				newHash1 %= MOD1
				newHash2 -= 1 << i
				newHash2 %= MOD2
			else:
				newHash1 += 1 << i
				newHash1 %= MOD1
				newHash2 += 1 << i
				newHash2 %= MOD2
			newKey = (newHash1, newHash2)
			if newKey in oddStrDict:
				cnt += oddStrDict[newKey]
print(cnt)
